<?php
require_once __DIR__ . '/../config.php';
$pdo->exec("CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,last_login DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
$pdo->exec("CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NULL) ENGINE=InnoDB");
try { $pdo->exec("ALTER TABLE products ADD COLUMN image VARCHAR(255) DEFAULT NULL"); } catch(Throwable $e) {}
$count=(int)$pdo->query("SELECT COUNT(*) FROM admins")->fetchColumn(); $error='';
if($count>0){exit('<h2>Admin setup is already complete.</h2><p><a href="login.php">Go to login</a></p>');}
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Enter a name, valid email and password of at least 8 characters.';else{$s=$pdo->prepare("INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);header('Location: login.php');exit;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Admin — IANOVA</title><style>body{font-family:Arial;background:#f3f6f4}.box{max-width:450px;margin:8vh auto;background:#fff;padding:28px;border-radius:15px}input{width:100%;box-sizing:border-box;padding:12px;margin:6px 0 15px}button{padding:12px;width:100%;background:#17352c;color:#fff;border:0;border-radius:8px}.err{color:#a22}</style><link rel="stylesheet" href="../assets/css/admin-theme.css?v=1"></head><body><div class="box"><h1>Create IANOVA Administrator</h1><p>This page can only create the first administrator.</p><?php if($error):?><p class="err"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post"><label>Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Password (8+ characters)</label><input type="password" name="password" minlength="8" required><button>Create administrator</button></form></div></body></html>
